/* shared helpers for the staff consoles */
(function(){
var BA=window.BA,ST=window.ST={BA:BA,D:BA.D,esc:BA.esc,$:function(i){return document.getElementById(i)}};
ST.staff=BA.jget('ba3_staff',null);
ST.rs=function(n){n=Math.round(+n||0);return '₹'+n.toLocaleString('en-IN')};
ST.num=function(n){return Math.round(+n||0).toLocaleString('en-IN')};
ST.log=function(what){var a=BA.jget('ba3_audit',[]);a.push({who:ST.staff?ST.staff.name:'System',role:ST.staff?(BA.ROLES&&BA.ROLES[ST.staff.role]?BA.ROLES[ST.staff.role].label:ST.staff.role):'',what:what,at:Date.now()});BA.jset('ba3_audit',a)};
ST.rng=function(seed){var a=seed>>>0;return function(){a=(a+0x6D2B79F5)>>>0;var t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}};
ST.ago=function(ts){var m=Math.round((Date.now()-ts)/60000);if(m<1)return 'just now';if(m<60)return m+' min ago';if(m<1440)return Math.round(m/60)+' h ago';return Math.round(m/1440)+' d ago'};
ST.dfmt=function(ts){return new Date(ts).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})};
ST.kpi=function(l,v,s){return '<div class="kpi"><small>'+l+'</small><b>'+v+'</b><span>'+(s||'')+'</span></div>'};
ST.head=function(t,sub,right){return '<div style="display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;align-items:end;margin-bottom:6px"><div><h1 style="font-size:clamp(26px,3vw,38px);letter-spacing:-.035em">'+t+'</h1><p style="color:var(--mute);margin:6px 0 0;max-width:80ch">'+sub+'</p></div>'+(right||'')+'</div>'};
ST.tabsHtml=function(defs,cur){return '<div class="pf" id="tabs" style="margin:18px 0 16px">'+defs.map(function(t){return '<button data-t="'+t[0]+'" class="'+(cur===t[0]?'on':'')+'">'+t[1]+'</button>'}).join('')+'</div>'};
ST.bars=function(series,labels,colors,w,h){/* stacked bars; series=[[..],[..]] */w=w||560;h=h||200;var n=labels.length,tot=labels.map(function(_,i){return series.reduce(function(a,s){return a+s[i]},0)}),mx=Math.max.apply(null,tot)||1,bw=w/n*.58,out='<svg viewBox="0 0 '+w+' '+(h+34)+'" style="width:100%;height:auto;max-height:260px" role="img">';
 for(var g=0;g<=3;g++){var y=h-g*h/3;out+='<line x1="0" x2="'+w+'" y1="'+y+'" y2="'+y+'" stroke="#e6e6ea"/><text x="0" y="'+(y-4)+'" font-size="10" fill="#8a8a93">'+ST.compact(mx*g/3)+'</text>'}
 labels.forEach(function(l,i){var x=i*(w/n)+(w/n-bw)/2,y=h;series.forEach(function(s,k){var bh=s[i]/mx*h;y-=bh;out+='<rect x="'+x+'" y="'+y+'" width="'+bw+'" height="'+Math.max(bh,0)+'" fill="'+colors[k]+'" rx="3"><title>'+l+': '+ST.rs(s[i])+'</title></rect>'});out+='<text x="'+(x+bw/2)+'" y="'+(h+18)+'" font-size="11" text-anchor="middle" fill="#55555e">'+l+'</text>'});
 return out+'</svg>'};
ST.compact=function(n){n=+n;return n>=1e7?'₹'+(n/1e7).toFixed(1)+' Cr':n>=1e5?'₹'+(n/1e5).toFixed(1)+' L':n>=1e3?'₹'+Math.round(n/1e3)+' k':'₹'+Math.round(n)};
ST.legend=function(items){return '<div style="display:flex;gap:16px;flex-wrap:wrap;font-size:13px;color:var(--mute);margin-top:6px">'+items.map(function(x){return '<span><i style="display:inline-block;width:10px;height:10px;border-radius:3px;background:'+x[1]+';margin-right:6px"></i>'+x[0]+'</span>'}).join('')+'</div>'};
ST.csv=function(name,rows){var t=rows.map(function(r){return r.map(function(c){c=String(c);return /[",\n]/.test(c)?'"'+c.replace(/"/g,'""')+'"':c}).join(',')}).join('\n');var a=document.createElement('a');a.href=URL.createObjectURL(new Blob([t],{type:'text/csv'}));a.download=name;document.body.appendChild(a);a.click();a.remove();BA.toast('Downloaded '+name)};
ST.table=function(cols,rows,cls){return '<div class="ov3"><table class="qt '+(cls||'')+'"><thead><tr>'+cols.map(function(c){return '<th>'+c+'</th>'}).join('')+'</tr></thead><tbody>'+(rows.length?rows.join(''):'<tr><td colspan="'+cols.length+'" style="color:var(--mute)">Nothing here yet.</td></tr>')+'</tbody></table></div>'};
ST.chip=function(t,c){var m={g:'#E3F6EA;color:#176B3A',a:'#FFF1D6;color:#8A5A00',r:'#FFE3EA;color:#A3123F',b:'#E5EEFF;color:#1F4AA8',n:'#EDEDF0;color:#55555e'};return '<span class="pill" style="align-self:flex-start;white-space:nowrap;background:'+(m[c]||m.n)+'">'+t+'</span>'};
ST.panel=function(t,inner,right){return '<section class="sc" style="padding:20px;margin-bottom:18px"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:12px"><h2 style="font:800 19px var(--f);letter-spacing:-.02em;margin:0">'+t+'</h2>'+(right||'')+'</div>'+inner+'</section>'};
})();
/* ---------- documents on file for a property (supplied by the portal admin) ---------- */
ST.docsFor=function(p){var d=[{n:'Sale notice',k:'notice',by:'Portal admin',at:p.notice},{n:'Valuation and encumbrance summary',k:'valuation',by:'Portal admin',at:p.notice},{n:'Possession and occupancy note',k:'possession',by:'Portal admin',at:p.notice}];(BA.jget('ba3_docs',{})[p.id]||[]).forEach(function(x){d.push({n:x.n,k:'file',by:x.by,at:x.at,data:x.data,type:x.type,size:x.size})});return d};
ST.docView=function(p,d){var c=BA.D.cities[p.city],mv=p.reserve/(1-p.disc/100),fx=BA.jget('ba3_fv',{})[p.id],row=function(a,b){return '<tr><td style="color:var(--mute);padding:4px 14px 4px 0">'+a+'</td><td><b>'+ST.esc(b)+'</b></td></tr>'},h='';
 if(d.k==='notice')h='<h3>Sale notice</h3><p style="color:var(--mute)">Sale of immovable property under the SARFAESI Act, 2002</p><table>'+row('Lender',p.bank)+row('Property',p.title)+row('Location',p.loc+', '+c.label+' '+p.pin)+row('Reserve price',BA.inr(p.reserve))+row('EMD',BA.inr(p.emd))+row('Notice date',p.notice)+row('Auction date',p.auction_full)+row('Possession',p.poss)+row('Inspection','By appointment with the authorised officer')+'</table>';
 else if(d.k==='valuation')h='<h3>Valuation and encumbrance summary</h3><table>'+row('Property',p.short+', '+p.size)+row('Reserve price',BA.inr(p.reserve))+row('Estimated market value',BA.inr(+mv.toFixed(1)))+row('Discount to market',p.disc+'%')+row('Encumbrances in notice','None disclosed. Independent search recommended.')+row('Field estimate',fx?BA.inr(fx.est)+' ('+fx.by+', '+fx.when+')':'Not yet visited')+'</table>';
 else if(d.k==='possession')h='<h3>Possession and occupancy note</h3><table>'+row('Possession per bank',p.poss)+row('Occupancy on site',fx?fx.occ:'Not yet recorded')+row('Access road',fx?fx.access:'Not yet recorded')+row('Boundaries match documents',fx?fx.boundary:'Not yet recorded')+row('Litigation or notices seen',fx?(fx.lit||'None seen'):'Not yet recorded')+'</table>';
 else h='<h3>'+ST.esc(d.n)+'</h3><p>'+(d.data?'<a class="btn out sm" href="'+d.data+'" target="_blank" download="'+ST.esc(d.n)+'">Open the file ↗</a>':'File on record: '+ST.esc(d.n)+'.')+'</p>';
 BA.box('<div style="max-height:70vh;overflow:auto">'+h+'<p style="color:var(--mute);font-size:12.5px;margin-top:14px">Supplied by '+ST.esc(d.by)+(d.at?' · '+ST.esc(d.at):'')+'. Prototype rendering of the document on file.</p></div>')};
/* ---------- seeded demo base shared by marketing, admin, leadership ---------- */
(function(){var ST=window.ST,BA=ST.BA;
var FN=['Anitha','Vikram','Divya','Arjun','Fatima','Suresh','Lakshmi','Rohan','Preeti','Karthik','Meena','Imran','Nikhil','Sowmya','Harish','Deepa','Ramesh','Pooja','Naveen','Shalini'],LN=['Raghavan','Shah','Menon','Reddy','Khan','Kumar','Iyer','Das','Nair','Rao','Pillai','Sheikh','Gowda','Varma','Joseph'];
ST.users=function(){var R=ST.rng(4242),cs=BA.ck,out=[],ov=BA.jget('ba3_adm_users',{});
 for(var i=0;i<64;i++){var r=R(),plan=r<.5?'Free':r<.66?'Pro pack':r<.78?'Pro used up':r<.95?'Free':'Pro + Premium property',c=cs[Math.floor(R()*cs.length)],u={id:'U'+(2000+i),name:FN[Math.floor(R()*FN.length)]+' '+LN[Math.floor(R()*LN.length)],phone:'9'+String(Math.floor(R()*1e9)).padStart(9,'0'),city:c,plan:plan,joined:Date.now()-Math.floor(R()*170+2)*864e5,last:Date.now()-Math.floor(R()*30)*864e5,status:'active',unl:plan.indexOf('Pro')===0?Math.floor(R()*6):0,live:false};if(ov[u.id])Object.assign(u,ov[u.id]);out.push(u)}
 var lu=BA.user();if(lu){var cr=BA.cr(),pl=cr.left>0?'Pro pack':cr.packs?'Pro used up':'Free';if(BA.hasPrem())pl=pl==='Free'?'Premium property':pl+' + Premium property';var o=ov['LIVE']||{};out.unshift(Object.assign({id:'LIVE',name:lu.name+' (this browser)',phone:lu.phone,city:BA.city,plan:pl,joined:Date.now(),last:Date.now(),status:'active',unl:cr.unl.length,live:true},o))}
 return out};
ST.setUser=function(id,patch){var ov=BA.jget('ba3_adm_users',{});ov[id]=Object.assign(ov[id]||{},patch);BA.jset('ba3_adm_users',ov)};
ST.ledger=function(){var R=ST.rng(777),out=[],rf=BA.jget('ba3_refunds',{});
 ST.users().filter(function(u){return !u.live&&u.plan!=='Free'}).forEach(function(u,i){var n=u.plan.indexOf('Pro')===0?1+Math.floor(R()*2):0;for(var k=0;k<n;k++){var pk=[['Residential',2360],['Agricultural',2950],['Industrial',5900],['Commercial',8850]][Math.floor(R()*4)];out.push({id:'P'+(5000+out.length),who:u.name,what:'Pro pack · 20 '+pk[0].toLowerCase()+' properties',amt:pk[1],at:Date.now()-Math.floor(R()*150)*864e5,kind:'pro'})}if(u.plan==='Premium'||u.plan==='Pro + Premium'){var m=[[1180,'Residential'],[2360,'Agricultural'],[3540,'Industrial'],[4720,'Commercial']][Math.floor(R()*4)];out.push({id:'P'+(5000+out.length),who:u.name,what:'Premium property · '+BA.D.cities[u.city].label+' · '+m[1].toLowerCase(),amt:m[0],at:Date.now()-Math.floor(R()*100)*864e5,kind:'prem'})}});
 BA.bk().filter(function(b){return b.status==='completed'||b.status==='accepted'||b.status==='requested'}).forEach(function(b){out.push({id:'C'+b.id,who:b.cust.name,what:'Consultation · '+b.lawyer,amt:b.fee,at:b.created,kind:'law'})});
 for(var i=0;i<localStorage.length;i++){var k=localStorage.key(i);if(k&&k.indexOf('ba3_rc_')===0){var ph=k.slice(7),lu=BA.user();BA.jget(k,[]).forEach(function(r,j){if(r.what.indexOf('Consultation')===0)return;out.push({id:'L'+ph+j,who:(lu&&lu.phone===ph?lu.name:ph)+' (this browser)',what:r.what,amt:r.amt,at:Date.now()-j*1000,kind:/Premium/.test(r.what)?'prem':'pro',live:true})})}}
 out.forEach(function(p){p.refunded=!!rf[p.id]});return out.sort(function(a,b){return b.at-a.at})};
})();
